#include <iostream>
#include <vector>
#include <queue>
#include <climits>
using namespace std;

struct Edge {
    int u, v;
    long long capacity, flow;
    long long cost;
    long long remaining() { return capacity - flow; }
    Edge() {}
    Edge(int _u, int _v, long long _cap, long long _flow, long long _cost)
        : u(_u), v(_v), capacity(_cap), flow(_flow), cost(_cost) {}
};

vector<int> g[8200];
vector<Edge> e;
int n, m, k, c, d;

void addEdge(int u, int v, long long cap, long long cost) {
    g[u].push_back((int)e.size());
    e.emplace_back(u, v, cap, 0, cost);
    g[v].push_back((int)e.size());
    e.emplace_back(v, u, 0, 0, -cost);
}

long long dist[8200], totalCost;
int pre[8200];
long long cap[8200], flow;
bool inQueue[8200];

void minCostFlow(int s, int t) {
    memset(inQueue, 0, sizeof(inQueue));
    flow = totalCost = 0;
    while (true) {
        fill(dist, dist + 8200, LLONG_MAX);
        dist[s] = 0;
        memset(pre, -1, sizeof(pre));
        pre[s] = 0;
        memset(cap, 0, sizeof(cap));
        cap[s] = LLONG_MAX;
        queue<int> q;
        q.push(s);
        inQueue[s] = true;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            inQueue[u] = false;
            for (int idx : g[u]) {
                Edge &edge = e[idx];
                if (edge.remaining() > 0 && dist[edge.v] > dist[u] + edge.cost + 1e-9) {
                    dist[edge.v] = dist[u] + edge.cost;
                    pre[edge.v] = idx;
                    cap[edge.v] = min(cap[u], edge.remaining());
                    if (!inQueue[edge.v]) {
                        q.push(edge.v);
                        inQueue[edge.v] = true;
                    }
                }
            }
        }
        if (pre[t] < 0) break;
        long long delta = cap[t];
        flow += delta;
        totalCost += delta * dist[t];
        for (int v = t; v != s; v = e[pre[v]].u) {
            e[pre[v]].flow += delta;
            e[pre[v] ^ 1].flow -= delta;
        }
    }
}

